export default function createIslands(api){
  const baseCenters=[{x:146,y:370,name:'Home'},{x:340,y:370,name:'Fern Key'},{x:340,y:165,name:'Old Orchard'},{x:565,y:165,name:'Stonehaven'},{x:760,y:305,name:'Cloud Rest'},{x:573,y:446,name:'Lighthouse'}];
  const baseEdges=[[0,1],[1,2],[2,3],[3,4],[4,5],[1,5],[3,5]];
  let built,visited,items,player,planks,relics,time,route,done,flash,chapter,transition,totalRelics;
  let centers,edges;
  const chapters=[{name:'The Green Keys',points:null,edges:null},{name:'Cloudwater Reach',points:[[146,300],[348,148],[348,432],[565,295],[775,145],[775,445]],edges:[[0,1],[0,2],[1,3],[2,3],[3,4],[3,5],[4,5]]},{name:'The Last Light',points:[[143,407],[273,184],[498,159],[719,241],[744,447],[483,432]],edges:[[0,1],[1,2],[2,3],[3,4],[4,5],[0,5],[2,5]]}];
  const R=69;
  const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
  function nearIsland(){let index=0,best=Infinity;centers.forEach((p,i)=>{const d=distance(p,player);if(d<best){best=d;index=i;}});return index;}
  function segmentDistance(p,a,b){const dx=b.x-a.x,dy=b.y-a.y,t=Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.y-a.y)*dy)/(dx*dx+dy*dy)));return Math.hypot(p.x-a.x-t*dx,p.y-a.y-t*dy);}
  function walkable(p){return centers.some(c=>distance(p,c)<R)||edges.some((e,i)=>built.has(i)&&segmentDistance(p,centers[e[0]],centers[e[1]])<19);}
  function beginChapter(){const def=chapters[chapter];centers=baseCenters.map((c,i)=>({...c,...(def.points?{x:def.points[i][0],y:def.points[i][1]}:{})}));edges=def.edges||baseEdges;built=new Set();visited=new Set([0]);planks=2;relics=0;route=[];player={x:centers[0].x,y:centers[0].y};items=centers.map((c,i)=>i===0?null:{x:c.x+20,y:c.y-15,collected:false,planks:i===5?0:i===3?2:1});flash=`${def.name}: find five relics and return to the lighthouse.`;hud();}
  function reset(){chapter=0;transition=0;totalRelics=0;time=0;done=false;beginChapter();api.setHint('Three island chapters await. Tap an island to connect and travel, or move with arrows/WASD and build with Space.');}

  function hud(){api.hud({Chapter:`${chapter+1}/3`,Relics:`${relics}/5`,Planks:planks,Islands:`${visited.size}/6`,Time:`${Math.floor(time)}s`});}
  function build(index){if(built.has(index))return true;if(planks<1){flash='Gather a wood bundle on an explored island first.';return false;}planks--;built.add(index);api.sound('tap');flash='Bridge built. Find the relic and wood on the next island.';hud();return true;}
  function path(from,to){const queue=[[from]],seen=new Set([from]);while(queue.length){const p=queue.shift(),last=p.at(-1);if(last===to)return p;edges.forEach(([a,b],i)=>{if(!built.has(i))return;const n=a===last?b:b===last?a:-1;if(n>=0&&!seen.has(n)){seen.add(n);queue.push([...p,n]);}});}return null;}
  function pointerDown(x,y){if(done||transition>0)return;const target=centers.findIndex(c=>Math.hypot(x-c.x,y-c.y)<R+14);if(target<0)return;const from=nearIsland();let p=path(from,target);if(!p){const edge=edges.findIndex(e=>e.includes(from)&&e.includes(target));if(edge<0){flash='This island has no direct bridge from here. Follow the dotted routes.';return;}if(!build(edge))return;p=[from,target];}route=p.map(i=>({...centers[i]}));if(!route.length)route=[{x,y}];const item=items[target];if(item&&!item.collected)route.push({x:item.x,y:item.y});else route.push({...centers[target]});}
  function buildNearby(){const from=nearIsland();let choice=-1,best=Infinity;edges.forEach(([a,b],i)=>{if(built.has(i)||(![a,b].includes(from)))return;const c=centers[from],other=centers[a===from?b:a],vx=other.x-c.x,vy=other.y-c.y,l=Math.hypot(vx,vy),entry={x:c.x+vx/l*(R-10),y:c.y+vy/l*(R-10)},d=distance(player,entry);if(d<best){best=d;choice=i;}});if(choice<0){flash='All bridges from this island are already built.';return;}if(best>65){flash='Walk toward the dotted bridge you want to build.';return;}build(choice);}
  function keyDown(k){if(k==='Space'||k===' ')buildNearby();}
  function update(dt){if(done)return;time+=dt;if(transition>0){transition-=dt;if(transition<=0){chapter++;beginChapter();}return;}const keys=api.input.keys;let dx=Number(keys.has('ArrowRight')||keys.has('d'))-Number(keys.has('ArrowLeft')||keys.has('a')),dy=Number(keys.has('ArrowDown')||keys.has('s'))-Number(keys.has('ArrowUp')||keys.has('w'));
    if(dx||dy){route=[];const l=Math.hypot(dx,dy);dx/=l;dy/=l;}else if(route.length){const p=route[0],d=distance(player,p);if(d<4){player.x=p.x;player.y=p.y;route.shift();}else{dx=(p.x-player.x)/d;dy=(p.y-player.y)/d;}}
    const speed=115;const nx={x:player.x+dx*speed*dt,y:player.y+dy*speed*dt};if(walkable(nx)){player.x=nx.x;player.y=nx.y;}else{if(walkable({x:nx.x,y:player.y}))player.x=nx.x;if(walkable({x:player.x,y:nx.y}))player.y=nx.y;}
    centers.forEach((c,i)=>{if(distance(player,c)<R)visited.add(i);});items.forEach((item,i)=>{if(!item||item.collected||distance(player,item)>19)return;item.collected=true;relics++;totalRelics++;planks+=item.planks;api.sound('win');flash=`Relic found. ${item.planks?`+${item.planks} bridge ${item.planks===1?'plank':'planks'}.`:'Bring all five to the lighthouse.'}`;});
    if(relics===5&&distance(player,centers[5])<20){if(chapter<2){transition=3;flash='Lighthouse lit. A new archipelago is appearing…';api.sound('win');}else{done=true;api.end(3000+Math.max(0,Math.round(1200-time*2)),'Every lighthouse is lit',`Three archipelagos explored · ${totalRelics} relics returned · ${Math.round(time)} seconds.`);}}hud();}
  function text(c,t,x,y,size,color,align='center'){c.font=`${size}px Arial`;c.fillStyle=color;c.textAlign=align;c.fillText(t,x,y);}
  function circle(c,x,y,r,color){c.fillStyle=color;c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.fill();}
  function draw(c){const bg=c.createLinearGradient(0,0,0,600);bg.addColorStop(0,['#b8cbd0','#9db8cb','#c0aab6'][chapter]);bg.addColorStop(1,['#d2dfd4','#c4d4df','#dbc6bd'][chapter]);c.fillStyle=bg;c.fillRect(0,0,960,600);for(let i=0;i<13;i++){const x=(i*183+time*(i%2?4:7))%1100-60,y=84+(i*79)%480;c.fillStyle='#eef0e5';c.globalAlpha=.35;c.beginPath();c.ellipse(x,y,85,12,0,0,7);c.fill();}c.globalAlpha=1;text(c,'Little Islands',43,45,30,'#344c45','left');text(c,`${chapters[chapter].name} · Chapter ${chapter+1} of 3 · ${totalRelics}/15 relics returned`,43,73,15,'#617a6c','left');
    edges.forEach(([a,b],i)=>{const start=centers[a],end=centers[b];c.save();if(!built.has(i)){c.strokeStyle='#657e6d66';c.lineWidth=2;c.setLineDash([4,7]);c.beginPath();c.moveTo(start.x,start.y);c.lineTo(end.x,end.y);c.stroke();}else{c.strokeStyle='#6c776344';c.lineWidth=28;c.beginPath();c.moveTo(start.x+2,start.y+6);c.lineTo(end.x+2,end.y+6);c.stroke();c.strokeStyle='#b89e75';c.lineWidth=25;c.beginPath();c.moveTo(start.x,start.y);c.lineTo(end.x,end.y);c.stroke();const len=distance(start,end),n=Math.floor(len/10);c.translate(start.x,start.y);c.rotate(Math.atan2(end.y-start.y,end.x-start.x));c.strokeStyle='#806d50';c.lineWidth=1.5;for(let k=0;k<n;k++){c.beginPath();c.moveTo(k*10,-12);c.lineTo(k*10,12);c.stroke();}}c.restore();});
    centers.forEach((p,i)=>{c.fillStyle='#839c9366';c.beginPath();c.ellipse(p.x+5,p.y+22,74,19,0,0,7);c.fill();c.fillStyle='#77877a';c.beginPath();c.moveTo(p.x-R,p.y);c.lineTo(p.x-33,p.y+84);c.lineTo(p.x+12,p.y+94);c.lineTo(p.x+R,p.y);c.fill();circle(c,p.x,p.y,R,visited.has(i)?'#b2c697':'#abbc99');circle(c,p.x-3,p.y-5,R-8,visited.has(i)?'#c1d1a9':'#b7c5a7');for(let j=0;j<8;j++){const x=p.x-47+(j*19)%83,y=p.y-35+(j*23)%62;if(j%3===0){circle(c,x,y,6,'#a8b989');circle(c,x+2,y-2,5,'#cddaaf');}else{c.fillStyle='#9cae7d';c.fillRect(x,y,2,7);}}text(c,p.name,p.x,p.y+R+20,11,'#5d7664');
      if(i===0){c.fillStyle='#e2d4ad';c.fillRect(p.x-25,p.y-26,43,35);c.fillStyle='#647e73';c.beginPath();c.moveTo(p.x-32,p.y-26);c.lineTo(p.x-4,p.y-49);c.lineTo(p.x+25,p.y-26);c.fill();c.fillStyle='#8c997b';c.fillRect(p.x-7,p.y-10,12,19);}
      if(i===5){c.fillStyle='#ede4c9';c.fillRect(p.x-14,p.y-39,28,49);c.fillStyle='#7e8f77';c.fillRect(p.x-19,p.y-50,38,14);c.fillStyle=relics===5?'#f4db88':'#526c66';c.fillRect(p.x-8,p.y-46,16,10);if(relics===5){c.globalAlpha=.25;circle(c,p.x,p.y-41,35,'#fff0a5');c.globalAlpha=1;}}
      const item=items[i];if(item&&!item.collected){const float=Math.sin(time*2+i)*3;circle(c,item.x,item.y+float,14,'#edf0c877');c.fillStyle='#b08c4c';c.beginPath();c.moveTo(item.x,item.y-10+float);c.lineTo(item.x+9,item.y+float);c.lineTo(item.x,item.y+10+float);c.lineTo(item.x-9,item.y+float);c.closePath();c.fill();c.strokeStyle='#f8e3a2';c.stroke();if(item.planks){c.fillStyle='#907f5e';c.fillRect(item.x-40,item.y+19,20,5);c.fillRect(item.x-36,item.y+26,20,5);}}});
    c.fillStyle='#42646055';c.beginPath();c.ellipse(player.x,player.y+10,12,5,0,0,7);c.fill();circle(c,player.x,player.y+1,9,'#f0e4bf');c.fillStyle='#5a7b72';c.fillRect(player.x-7,player.y-1,14,15);circle(c,player.x,player.y-7,7,'#edd9b3');c.fillStyle='#c3986c';c.fillRect(player.x-8,player.y-13,16,5);c.fillRect(player.x-4,player.y-17,9,5);
    c.fillStyle='#eff2e2dd';c.beginPath();c.roundRect(43,543,874,35,6);c.fill();text(c,flash,60,567,14,'#587054','left');if(transition>0){c.fillStyle='#344c45ee';c.beginPath();c.roundRect(225,225,510,135,12);c.fill();text(c,'Lighthouse restored',480,273,29,'#e7edcf');text(c,`Sailing to ${chapters[chapter+1].name}…`,480,314,17,'#bfcfb0');}
  }
  return{reset,update,draw,pointerDown,keyDown};
}

